const miniGames=[{title:'Picture & Word Match',intro:'Match real photos of a park animal and plant with their field-guide words.'},{title:'Park Story Time',intro:'Read a three-sentence park story, then choose the detail you remember.'},{title:'Pack for the Hike',intro:'Choose useful hiking gear to pack for a safe park adventure.'},{title:'Wild Word Scramble',intro:'Unscramble a park animal’s name. Use the clue and field-guide photo to help.'},{title:'Habitat Builder',intro:'Build a mini habitat using this park’s landscape, plant, and animal.'},{title:'Junior Ranger Trail',intro:'Find the trail through the rocks and reach the park lookout.'}];
