let progress=readProgress(),current=Math.min(progress.current,route.length-1),gameState=newGameState(),parkPhotos={landscape:'',animal:'',plant:''},cameraPhotos={landscape:'',animal:'',plant:''},cameraPhotoErrors={},photoRequest=0,favoriteParks=readFavorites(),photoAlbums=readPhotoAlbums(),journalOpen=false;
