function readCustomizer(){const form=document.getElementById('rangerSetupForm');if(!form)return rangerProfile||rangerDefaults;const value=name=>form.elements[name]?.value;return {gender:value('gender'),skin:value('skin'),hair:value('hair'),hairColor:value('hairColor'),eyeColor:value('eyes'),outfitColor:value('outfit')}}
function setupRanger(){const panel=document.getElementById('rangerSetup'),form=document.getElementById('rangerSetupForm'),name=document.getElementById('rangerName'),edit=document.getElementById('editRangerButton'),cancel=document.getElementById('cancelRangerEdit');const open=()=>{name.value=rangerProfile?.name||'';const appearance=rangerProfile||rangerDefaults;for(const key of ['race','skin','gender','hair','hairColor','eyeColor','outfitColor'])if(form.elements[key])form.elements[key].value=appearance[key];cancel.hidden=!rangerProfile?.name;panel.hidden=false;renderRangerCompanion();name.focus()};edit.addEventListener('click',open);cancel.addEventListener('click',()=>{if(rangerProfile?.name){panel.hidden=true;renderRangerCompanion()}});form.querySelectorAll('select').forEach(control=>control.addEventListener('change',renderRangerCompanion));form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;rangerProfile={name:name.value.trim().slice(0,20),...readCustomizer(),race:form.elements.race.value};try{localStorage.setItem('park-pals-ranger-profile-v1',JSON.stringify(rangerProfile))}catch(e){}panel.hidden=true;renderRangerCompanion();showToast(`Ready to explore, ${rangerProfile.name}!`)});panel.addEventListener('keydown',event=>{if(event.key==='Escape'&&!rangerProfile?.name)event.preventDefault()});if(!rangerProfile?.name)open();else renderRangerCompanion()}
function renderBadge(){const i=current,hasNext=i+1<route.length,arrived=progress.travelled.includes(i);document.getElementById('gameArea').innerHTML=`<div class="badge-reward"><div class="badge-star">🏅</div><strong>Junior Ranger badge earned!</strong><p>${esc(route[i].name)} Park · Badge ${String(i+1).padStart(2,'0')} of 64</p>${hasNext?`<div class="trip-map-wrap"><div class="map-heading"><span>ROAD TRIP ROUTE</span><span>${esc(route[i].name)} → ${esc(route[i+1].name)}</span></div>${makeTripMap(i)}</div><div id="arrivalMessage" class="arrival-message">${arrived?'You made it! The next park is ready.':'Nice work! Your car is heading to the next park…'}</div><button class="next-button" id="nextButton" ${arrived?'':'disabled'}>${arrived?`Arrived! Explore ${esc(route[i+1].name)} →`:'Driving to the next park…'}</button>`:'<strong>🎉 You completed the whole road trip!</strong>'}</div>`;if(!hasNext)return;const button=document.getElementById('nextButton');if(arrived){button.onclick=()=>selectPark(i+1);return}setTimeout(()=>{if(!progress.travelled.includes(i))progress.travelled.push(i);progress.travelled.sort((a,b)=>a-b);save();renderRoute();if(current===i){const b=document.getElementById('nextButton'),m=document.getElementById('arrivalMessage');if(b){b.disabled=false;b.textContent=`Arrived! Explore ${route[i+1].name} →`;b.onclick=()=>selectPark(i+1)}if(m)m.textContent=`You made it! ${route[i+1].name} is ready.`}},3000)}
function mapPoint(i){const [lon,lat]=parkCoords[route[i].name]||[-98,38];if(lat>52)return [27+(lon+179)/49*135,224+(68-lat)/16*107];if(lon< -140&&lat>18)return [230+(lon+161)/8*58,314+(23-lat)*4];if(lon< -160)return [580,343];if(lon> -68&&lat<23)return [533,280];return [70+(lon+126)/60*500,20+(50-lat)/27*310]}
function makeTripMap(i){
  const [x1,y1]=mapPoint(i),[x2,y2]=mapPoint(i+1),cx=(x1+x2)/2,cy=(y1+y2)/2-18,d=`M ${x1} ${y1} Q ${cx} ${cy} ${x2} ${y2}`;
  const dots=route.map((_,n)=>{const [x,y]=mapPoint(n);return `<circle class="map-dot ${n===i?'map-current':n===i+1?'map-next':''}" cx="${x}" cy="${y}" r="${n===i||n===i+1?3.5:1.7}"/>`}).join('');
  return `<svg class="usa-map" viewBox="0 0 600 360" role="img" aria-label="Car traveling from ${esc(route[i].name)} to ${esc(route[i+1].name)} on a map of the United States with state borders"><image href="usa-state-map.png" x="0" y="0" width="600" height="360" preserveAspectRatio="none"/><path class="map-route-line" d="${d}"/><g class="car-marker"><text x="0" y="5">🚙<animateMotion dur="3s" fill="freeze" path="${d}"/></text></g>${dots}<circle class="map-ring" cx="${x1}" cy="${y1}" r="6"/><circle class="map-ring next-ring" cx="${x2}" cy="${y2}" r="6"/><text class="map-pin-label" x="${x1+7}" y="${y1-7}">${esc(route[i].name)}</text><text class="map-pin-label next-label" x="${x2+7}" y="${y2-7}">${esc(route[i+1].name)}</text></svg>`
}
function requestPhotoAsset(i,kind){
  const key=`${i}:${kind}`;
  if(photoAssets.has(key))return Promise.resolve(photoAssets.get(key));
  if(photoPromises.has(key)){const queued=photoQueue.find(t=>t.key===key);if(queued&&i===current){queued.priority=0;photoQueue.sort((a,b)=>a.priority-b.priority)}return photoPromises.get(key)}
  let resolve;const promise=new Promise(r=>resolve=r);photoPromises.set(key,promise);
  const enqueue=()=>{photoQueue.push({key,i,kind,priority:i===current?0:1,resolve});photoQueue.sort((a,b)=>a.priority-b.priority);runPhotoQueue()};
  if(/^camera/.test(kind))Promise.all(['landscape','animal','plant'].map(k=>requestPhotoAsset(i,k))).then(enqueue);else enqueue();
  return promise
}
function runPhotoQueue(){while(photoWorkers<PHOTO_WORKERS&&photoQueue.length){const t=photoQueue.shift();photoWorkers++;searchAndLoadPhoto(t.i,t.kind).then(asset=>{if(asset)photoAssets.set(t.key,asset);else photoFailed++;t.resolve(asset)}).catch(()=>{photoFailed++;t.resolve(null)}).finally(()=>{photoWorkers--;photoLoaded++;updatePhotoLoadStatus();runPhotoQueue()})}}
