  const qs=baseKind==='landscape'?[`"${p.name} National Park"`,`"${p.name}" national park landscape`]:[`"${term}" "${p.name} National Park"`,`"${term}"`];
  for(const q of qs){try{const url=`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(`filetype:bitmap ${q}`)}&gsrnamespace=6&gsrlimit=10&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=${width}&format=json&origin=*`,res=await fetch(url);if(!res.ok)continue;const data=await res.json(),pages=Object.values(data.query?.pages||{}).filter(x=>x.imageinfo?.[0]?.thumburl&&!dryTortugasTitles.has(x.title.replace(/^File:/,'').replace(/_/g,' ').trim().toLowerCase())&&(!cameraMode||!lookAroundSources.has(x.imageinfo[0].descriptionurl)&&!lookAroundSources.has(x.imageinfo[0].thumburl))),scoreFn=baseKind==='landscape'?score:speciesScore;pages.sort((a,b)=>scoreFn(b.title,term)-scoreFn(a.title,term));for(const page of pages){const info=page.imageinfo[0],src=info.thumburl||info.url,loaded=await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(true);im.onerror=()=>resolve(false);im.src=src});if(loaded)return {url:src,source:info.descriptionurl,artist:info.extmetadata?.Artist?.value?plain(info.extmetadata.Artist.value):'Wikimedia Commons contributor'}}}catch(e){}}
