function loadRealPhoto(p){const i=route.indexOf(p),req=++photoRequest,intro=document.getElementById('introPhoto'),hero=document.getElementById('parkHero'),credit=document.getElementById('photoCredit'),titleKind=p.name==='Dry Tortugas'||p.name==='Grand Teton'||p.name==='New River Gorge'||p.name==='Hot Springs'?'title':'landscape';hero.style.backgroundImage='';intro.style.backgroundImage='';credit.textContent='';document.querySelectorAll('.hero-loading').forEach(e=>e.style.display='grid');requestPhotoAsset(i,titleKind).then(a=>{if(req!==photoRequest)return;if(!a){document.querySelectorAll('.hero-loading').forEach(e=>e.textContent='Park photo unavailable');return}hero.style.backgroundImage=`url("${a.url}")`;intro.style.backgroundImage=`url("${a.url}")`;document.querySelectorAll('.hero-loading').forEach(e=>e.style.display='none');credit.innerHTML=`<a href="${esc(a.source)}" target="_blank" rel="noreferrer">Photo: ${esc(a.artist)} · View photo ↗</a>`});requestPhotoAsset(i,'landscape').then(a=>{if(req!==photoRequest||!a)return;parkPhotos.landscape=a.url;const view=document.getElementById('landscapePhoto');if(view)view.innerHTML=`<img src="${esc(a.url)}" alt="Real landscape photograph of ${esc(p.fullName)}"><a class="image-credit" href="${esc(a.source)}" target="_blank" rel="noreferrer">Photo ↗</a>`;if(current===i&&!progress.complete.includes(current))renderMiniGame()})}
function loadSpeciesPhoto(term,id,i){const kind=id==='animalPhoto'?'animal':'plant';requestPhotoAsset(i,kind).then(a=>{if(current!==i)return;const el=document.getElementById(id);if(!el)return;if(!a){el.innerHTML='<span role="status">Photo unavailable</span>';return}parkPhotos[kind]=a.url;el.innerHTML=`<img src="${esc(a.url)}" alt="Real photograph of ${esc(term)}"><a class="image-credit" href="${esc(a.source)}" target="_blank" rel="noreferrer" title="Photo by ${esc(a.artist)}">Photo ↗</a>`;if(current%6===0&&!progress.complete.includes(current))renderMiniGame()})}
function updatePhotoLoadStatus(){const el=document.getElementById('photoLoadStatus');if(!el)return;const total=route.length*6+4;el.textContent=photoLoaded>=total?`Loaded ${photoAssets.size} of ${total} park photos${photoFailed?` · ${photoFailed} unavailable`:''}`:`Loading park photos automatically · ${photoLoaded} of ${total}`}
function preloadAllPhotos(){route.forEach((p,i)=>{['landscape','animal','plant'].forEach(kind=>requestPhotoAsset(i,kind));if(p.name==='Dry Tortugas'||p.name==='Grand Teton'||p.name==='New River Gorge'||p.name==='Hot Springs')requestPhotoAsset(i,'title')});route.forEach((_,i)=>['cameraLandscape','cameraAnimal','cameraPlant'].forEach(kind=>requestPhotoAsset(i,kind)));updatePhotoLoadStatus()}
function speciesScore(title,term){const t=title.toLowerCase(),s=term.toLowerCase();let n=t.includes(s)?10:0;if(/photo|file:/i.test(title))n++;if(/diagram|drawing|map|logo|icon|illustration|specimen|sketch/i.test(t))n-=12;return n}
function score(title,slug){const t=title.toLowerCase(),s=slug.toLowerCase();let n=t.includes(s)?12:0;if(t.includes('national park'))n+=3;if(/landscape|sunrise|mountain|waterfall|glacier|canyon|forest|view|lake|river|coast|arch|dune/i.test(t))n+=3;if(/map|logo|flag|badge|poster|sign/i.test(t))n-=10;return n}
function plain(s){const e=document.createElement('div');e.innerHTML=s;return e.textContent||''}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function cap(s){return s.charAt(0).toUpperCase()+s.slice(1)}
function article(s){return /^[aeiou]/i.test(s)?`an ${s}`:`a ${s}`}
function shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function setupTextSize(){const button=document.getElementById('textSizeToggle');let size=0;try{size=Math.max(0,Math.min(2,Number(localStorage.getItem('park-pals-text-size'))||0))}catch(e){}const apply=()=>{document.body.classList.toggle('large-text',size===1);document.body.classList.toggle('extra-large-text',size===2);button.setAttribute('aria-pressed',String(size>0));button.setAttribute('aria-label',size===0?'Make text larger':size===1?'Make text even larger':'Use standard text size');button.textContent=size===0?'A+ Larger text':size===1?'A++ Even larger text':'A− Standard text'};button.addEventListener('click',()=>{size=(size+1)%3;try{localStorage.setItem('park-pals-text-size',String(size))}catch(e){}apply()});apply()}
